import React, { useState, useRef } from 'react';
import { Upload, Sparkles } from 'lucide-react';

export default function WelcomeScreen() {
  const [isHovering, setIsHovering] = useState(false);
  const fileInputRef = useRef(null);

  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      console.log('File uploaded:', file.name);
      // Add your file handling logic here
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen p-6 relative overflow-hidden bg-gray-50">
      {/* Animated Background Blobs */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-20 left-10 w-72 h-72 bg-indigo-300 rounded-full mix-blend-multiply filter blur-xl opacity-40 animate-pulse"></div>
        <div className="absolute top-40 right-10 w-72 h-72 bg-purple-300 rounded-full mix-blend-multiply filter blur-xl opacity-40 animate-pulse" style={{animationDelay: '2s'}}></div>
        <div className="absolute bottom-20 left-1/2 w-72 h-72 bg-pink-300 rounded-full mix-blend-multiply filter blur-xl opacity-40 animate-pulse" style={{animationDelay: '4s'}}></div>
      </div>

      {/* Main Content */}
      <div className="relative z-10 max-w-xl w-full">
        {/* Header */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center mb-3">
            <Sparkles className="w-8 h-8 text-indigo-600 animate-pulse" />
          </div>
          <h1 className="text-4xl font-bold text-gray-900 mb-3">
            <span className="bg-gradient-to-r from-indigo-600 to-purple-600 bg-clip-text text-transparent">
              Welcome to Your AI Interview
            </span>
          </h1>
          <p className="text-lg text-gray-600">
            Let's get started on your journey to success
          </p>
        </div>

        {/* Upload Button */}
        <div className="flex justify-center mb-8">
          <button
            onClick={() => fileInputRef.current?.click()}
            onMouseEnter={() => setIsHovering(true)}
            onMouseLeave={() => setIsHovering(false)}
            className="relative group"
          >
            <div className="absolute -inset-1 bg-gradient-to-r from-indigo-600 to-purple-600 rounded-xl blur opacity-60 group-hover:opacity-100 transition duration-300"></div>
            <div className="relative bg-gradient-to-r from-indigo-600 to-purple-600 text-white px-8 py-3 rounded-xl font-semibold text-base shadow-lg transform transition-all duration-200 hover:scale-105 active:scale-95 flex items-center gap-2">
              <Upload className={`w-5 h-5 transition-transform duration-300 ${isHovering ? 'rotate-12' : ''}`} />
              Upload Resume
            </div>
          </button>
        </div>

        {/* Hidden File Input */}
        <input
          ref={fileInputRef}
          type="file"
          accept=".pdf,.docx"
          onChange={handleFileUpload}
          className="hidden"
        />

        {/* Bottom Info */}
        <div className="text-center px-4">
          <p className="text-sm text-gray-600 mb-2 font-medium">
            🔒 Your data is secure and processed locally
          </p>
          <p className="text-sm text-gray-500">
            Supported: PDF, DOCX • Max: 10MB
          </p>
        </div>
      </div>
    </div>
  );
}
